import{_ as e,C as a,o as n,c as l,j as d,a as s,E as r,a2 as i}from"./chunks/framework.DGvnA5EY.js";const u="/workbuddy-guide/assets/01-file-tidy.BYdaKh24.png",c=JSON.parse('{"title":"第 12 章 从整理桌面文件这些小事做起","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 桌面乱成垃圾场、下载文件夹塞了几百个无名文件——这种\\"小事\\"最消耗心力， 却最容易被一直拖着。WorkBuddy 能直接操作你电脑上的文件，把它当成保洁： 批量重命名、按类型归档、找重复、挑大文件…","frontmatter":{"title":"第 12 章 从整理桌面文件这些小事做起"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 从整理桌面文件这些小事做起/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 从整理桌面文件这些小事做起/index.md","lastUpdated":1791625328000}'),p={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 从整理桌面文件这些小事做起/index.md"};function h(b,t,k,g,q,m){const o=a("Paywall");return n(),l("div",null,[t[0]||(t[0]=d("h1",{id:"第-12-章-从整理桌面文件这些小事做起",tabindex:"-1"},[s("第 12 章 从整理桌面文件这些小事做起 "),d("a",{class:"header-anchor",href:"#第-12-章-从整理桌面文件这些小事做起","aria-label":'Permalink to "第 12 章 从整理桌面文件这些小事做起"'},"​")],-1)),t[1]||(t[1]=d("blockquote",null,[d("p",null,"内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）")],-1)),r(o,{part:"2",variant:"banner"}),t[2]||(t[2]=i('<p>桌面乱成垃圾场、下载文件夹塞了几百个无名文件——这种&quot;小事&quot;最消耗心力， 却最容易被一直拖着。WorkBuddy 能直接操作你电脑上的文件，把它当成保洁： 批量重命名、按类型归档、找重复、挑大文件。<strong>但动文件有风险</strong>，这一章重点教 你安全地让它干，并把整理规则固化成零成本技能。</p><p><img src="'+u+'" alt="一只小黑蹲在一堆散落的文件前，用双手把文件摞整齐" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;整理文件&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这次整理要交付什么" tabindex="-1">一、先想清楚：这次整理要交付什么 <a class="header-anchor" href="#一、先想清楚-这次整理要交付什么" aria-label="Permalink to &quot;一、先想清楚：这次整理要交付什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>整理完要什么状态</td><td>桌面只留常用，其余按类型归档、能按名找到</td></tr><tr><td>受众</td><td>谁会用这些文件</td><td>主要是你自己，可能涉及家人/同事共享目录</td></tr><tr><td>材料</td><td>哪些文件参与整理</td><td>仅&quot;下载&quot;&quot;桌面&quot;两个文件夹，不碰工作盘</td></tr><tr><td>格式</td><td>整理后的目录结构</td><td>按&quot;类型 / 年月&quot;两级目录</td></tr><tr><td>验收</td><td>怎么判断整理成功</td><td>原文件无丢失、备份存在、命名规则一致</td></tr></tbody></table><h2 id="二、先选对-skill-文件整理的组合" tabindex="-1">二、先选对 Skill：文件整理的组合 <a class="header-anchor" href="#二、先选对-skill-文件整理的组合" aria-label="Permalink to &quot;二、先选对 Skill：文件整理的组合&quot;">​</a></h2><p>WorkBuddy 整理本地文件，本质是 <strong>Agent 模式下的本地文件操作能力</strong>，不一定需要 单独技能；但配合下面这些更稳：</p><table tabindex="0"><thead><tr><th>方式 / Skill</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>通用 Agent（本地文件操作）</strong></td><td>重命名、移动、归档、查找</td><td>直接下指令让它操作指定目录</td><td>必须开启权限确认，永远先预览后执行</td></tr><tr><td><strong>手动复制 / 备份</strong></td><td>整理前的安全网</td><td>先把待整理目录复制一份到备份</td><td>不可逆操作前必做</td></tr><tr><td><strong>Browser Automation</strong></td><td>网盘 / 网页端文件整理</td><td>整理云盘里的散文件</td><td>需要账号授权，注意隐私</td></tr><tr><td><strong>skill-creator（零成本）</strong></td><td>把整理规则固化</td><td>&quot;每周整理下载文件夹&quot;做成技能</td><td>跑顺后固化，下次一句话触发</td></tr></tbody></table><blockquote><p>铁律：动文件的指令，<strong>认准官方源、不开全自动批准</strong>。AI 很听指令，但&quot;删/移&quot; 是不可逆的，这道闸得你守。</p></blockquote>',9)),r(o,{part:"2"}),t[3]||(t[3]=d("p",null,[d("em",null,"—— 以上试读到此为止。第二篇共 11 章，完整版 PDF 包含全部实操内容。——")],-1))])}const y=e(p,[["render",h]]);export{c as __pageData,y as default};
